#include "stdlib/blas/ext/base/cmskrev.h"
#include "stdlib/complex/float32/ctor.h"
#include <stdint.h>
#include <stdio.h>

int main( void ) {
	// Create a strided array of interleaved real and imaginary components:
	float x[] = { 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f };

	// Create a mask array:
	const uint8_t mask[] = { 0, 0, 0, 1, 0, 0, 0, 0 };

	// Specify the number of elements:
	const int N = 8;

	// Specify strides:
	const int strideX = 1;
	const int strideMask = 1;

	// Reverse the array:
	stdlib_strided_cmskrev( N, (stdlib_complex64_t *)x, strideX, mask, strideMask );

	// Print the result:
	for ( int i = 0; i < N; i++ ) {
		printf( "x[ %i ] = %f + %fi\n", i, x[ i*2 ], x[ (i*2)+1 ] );
	}
}
